library(shiny)
library(bslib)
library(mirai)
library(promises)
library(openxlsx)

TIMER_NOT_STARTED <- 0L
TIMER_RUNNING <- 1L
TIMER_FINISHED <- 2L

EMPTY_TEXT <- ""

if(!("MySet" %in% names(Progress$public_methods)))
{
	Progress$set("public", "MySet", function(value, message, detail, session = getDefaultReactiveDomain()) {
		self$set(value, message, "")
